"use strict";

// imports/common/node-base.ts
function execNode(handlerFunction, errorOutcome) {
  try {
    handlerFunction();
  } catch (e) {
    logger.error("Exception: " + e);
    logger.debug("Stack trace " + e.stack);
    action.goTo(errorOutcome);
  }
}

// imports/common/state.ts
function putStatePath(path, value) {
  var transient = arguments.length > 2 && arguments[2] !== undefined ? arguments[2] : false;
  var keys = path.split(".");
  var rootKey = keys[0];
  var newValue = null;
  if (keys.length === 1) {
    newValue = value;
  } else {
    var existing = nodeState.get(rootKey) || {};
    newValue = existing;
    for (var i = 1; i < keys.length - 1; i++) {
      var key = keys[i];
      newValue[key] = newValue[key] || {};
      newValue = newValue[key];
    }
    newValue[keys[keys.length - 1]] = value;
  }
  if (transient) {
    nodeState.putTransient(rootKey, newValue);
  } else {
    nodeState.putShared(rootKey, newValue);
  }
}

// imports/common/http.ts
function getHttpHeader(headerName) {
  var header = requestHeaders.get(headerName);
  return header ? String(header.get(0)) : null;
}

// packages/headers-to-state/src/headers-to-state.ts
var nodeOutcomes = {
  OK: "OK",
  MISSING_HEADERS: "Missing Headers",
  ERROR: "Error"
};
execNode(function () {
  var missingHeaders = false;
  Object.keys(properties.headers).forEach(function (headerName) {
    logger.debug("Reading header " + headerName);
    var statePath = properties.headers[headerName];
    var headerValue = getHttpHeader(headerName);
    if (!headerValue) {
      logger.debug("Header not found - continuing");
      missingHeaders = true;
      return;
    }
    logger.debug("Saving header ".concat(headerName, " value ").concat(headerValue, " to state variable ").concat(statePath));
    putStatePath(statePath, headerValue);
  });
  action.goTo(missingHeaders ? nodeOutcomes.MISSING_HEADERS : nodeOutcomes.OK);
}, nodeOutcomes.ERROR);
